private static readonly Lazy<Index> SharedIndex =
    new Lazy<Index>(BuildIndex, LazyThreadSafetyMode.ExecutionAndPublication);

public static Index Index => SharedIndex.Value;   // built exactly once, even under contention

private readonly ConcurrentDictionary<Key, Lazy<Report>> _cache = new();

public Report Get(Key key) =>
    _cache.GetOrAdd(key, static k => new Lazy<Report>(() => Compose(k))).Value;
